/**
 * Comparison chart rendered to PNG for MCP image content: traces vs distance (speed, throttle,
 * brake, gear, steering, delta) for two laps plus a track map whose line is colored by where time
 * is lost/gained (zoomed on a corner with both driven lines when a corner is given).
 *
 * The SVG is generated by hand (no DOM) and rasterized with @resvg/resvg-js. Dark theme:
 * surface #1a1a19; "você" orange and "referência" aqua (categorical slots 2/3, validated
 * all-pairs on dark); delta uses the blue (ganhando) ↔ red (perdendo) diverging pair with a
 * neutral gray midpoint, and always comes with text labels.
 */

import type { ChartChannel, ChartData } from '@gt7/analysis';
import { formatDelta, formatLapTime } from '@gt7/analysis';
import { type AnalysisService, findCorner } from '@gt7/core';
import type { ComparisonReferenceKind, Id, LapComparisonResult } from '@gt7/shared';
import { Resvg } from '@resvg/resvg-js';

const C = {
  surface: '#1a1a19',
  panel: '#212120',
  grid: '#33332f',
  axis: '#55554f',
  text: '#f0efec',
  text2: '#c3c2b7',
  muted: '#8f8e86',
  you: '#d95926',
  ref: '#199e70',
  gain: '#3987e5',
  loss: '#e66767',
  mid: '#8a8984',
  asphalt: '#383835',
};
const FONT = "'Segoe UI', 'Helvetica Neue', Arial, sans-serif";

export interface MapPoint {
  x: number;
  z: number;
}

export interface ComparisonChartInput {
  title: string;
  subtitle: string;
  youLabel: string;
  refLabel: string;
  chart: ChartData;
  /** Lap ids of the two laps in `chart` (subject, reference). */
  lapId: Id;
  refLapId: Id;
  /** Full track centerline (world X/Z). */
  track: MapPoint[];
  /** Subject driven line inside [chart.fromM, chart.toM] with delta rate (s/100 m). */
  subject: (MapPoint & { rate: number })[];
  /** Reference driven line inside the same range. */
  reference: MapPoint[];
  corners: { id: string; label: string; x: number; z: number }[];
  /** Zoomed map (corner chart) instead of the full track. */
  zoom: boolean;
  /** Brake points on the map (zoom only). */
  brakePoints?: { who: 'you' | 'ref'; x: number; z: number }[];
  /** Vertical markers on the traces. */
  markers: { label: string; distanceM: number }[];
  footer?: string[];
}

const esc = (s: string) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const n1 = (v: number) => (Math.round(v * 10) / 10).toString();

function niceStep(span: number, target: number): number {
  const raw = span / Math.max(1, target);
  const p = 10 ** Math.floor(Math.log10(raw));
  const m = raw / p;
  return (m < 1.5 ? 1 : m < 3 ? 2 : m < 7 ? 5 : 10) * p;
}

function hexToRgb(h: string): [number, number, number] {
  const v = Number.parseInt(h.slice(1), 16);
  return [(v >> 16) & 255, (v >> 8) & 255, v & 255];
}

function mix(a: string, b: string, t: number): string {
  const ra = hexToRgb(a);
  const rb = hexToRgb(b);
  const c = ra.map((x, i) => Math.round(x + (rb[i]! - x) * t));
  return `#${c.map((x) => x.toString(16).padStart(2, '0')).join('')}`;
}

/** Diverging color of a delta rate (s/100 m): + losing (red), − gaining (blue). */
export function deltaColor(rate: number, maxAbs = 0.08): string {
  if (!Number.isFinite(rate)) return C.mid;
  const t = Math.min(1, Math.abs(rate) / maxAbs);
  const q = Math.round(t * 4) / 4; // 5 levels per arm keeps the SVG small
  return mix(C.mid, rate > 0 ? C.loss : C.gain, q);
}

interface PanelSpec {
  channel: ChartChannel;
  title: string;
  height: number;
  /** Fixed y range (else data range). */
  range?: [number, number];
  step?: boolean;
}

const PANELS: PanelSpec[] = [
  { channel: 'speedKmh', title: 'Velocidade (km/h)', height: 210 },
  { channel: 'throttle', title: 'Acelerador (%)', height: 95, range: [0, 100] },
  { channel: 'brake', title: 'Freio (%)', height: 95, range: [0, 100] },
  { channel: 'gear', title: 'Marcha', height: 80, step: true },
  { channel: 'steering', title: 'Volante (rad)', height: 95 },
  { channel: 'deltaS', title: 'Delta (s) · + = você perdendo', height: 120 },
];

/** Builds the comparison chart SVG (1400 px wide). */
export function renderComparisonSvg(input: ComparisonChartInput): string {
  const W = 1400;
  const left = 70;
  const plotW = 860;
  const mapX = left + plotW + 40;
  const mapW = W - mapX - 30;
  const top = 92;
  const gap = 14;
  const { chart } = input;
  const xs = chart.distanceM;
  const from = chart.fromM;
  const to = chart.toM;
  const sx = (d: number) => left + ((d - from) / Math.max(1e-9, to - from)) * plotW;
  const series = (lap: Id, ch: ChartChannel) =>
    chart.series.find((s) => s.lapId === lap && s.channel === ch)?.values ?? null;

  const panels = PANELS.filter((p) => {
    if (p.channel === 'deltaS') return !!series(input.lapId, 'deltaS');
    return !!series(input.lapId, p.channel) || !!series(input.refLapId, p.channel);
  });
  const out: string[] = [];
  let y = top;
  const panelBoxes: { y: number; h: number }[] = [];

  for (const p of panels) {
    const h = p.height;
    panelBoxes.push({ y, h });
    const lines: { vals: (number | null)[]; color: string; width: number }[] = [];
    if (p.channel === 'deltaS') {
      lines.push({ vals: series(input.lapId, 'deltaS')!, color: C.text, width: 1.8 });
    } else {
      const r = series(input.refLapId, p.channel);
      const a = series(input.lapId, p.channel);
      if (r) lines.push({ vals: r, color: C.ref, width: 2 });
      if (a) lines.push({ vals: a, color: C.you, width: 2 });
    }
    const all = lines
      .flatMap((l) => l.vals)
      .filter((v): v is number => v !== null && Number.isFinite(v));
    let [lo, hi] = p.range ?? [Math.min(...all), Math.max(...all)];
    if (!Number.isFinite(lo) || !Number.isFinite(hi)) [lo, hi] = [0, 1];
    if (p.channel === 'deltaS') {
      const m = Math.max(Math.abs(lo), Math.abs(hi), 0.05);
      [lo, hi] = [Math.min(lo, 0) - m * 0.08, Math.max(hi, 0) + m * 0.08];
    } else if (!p.range) {
      const pad = (hi - lo) * 0.08 || 1;
      lo -= pad;
      hi += pad;
    }
    if (p.channel === 'gear') {
      lo = Math.max(0, Math.floor(lo));
      hi = Math.ceil(hi);
    }
    const sy = (v: number) => y + h - ((v - lo) / Math.max(1e-9, hi - lo)) * h;
    out.push(
      `<rect x="${left}" y="${y}" width="${plotW}" height="${h}" fill="${C.panel}" rx="4"/>`,
    );
    // horizontal grid + y labels
    const step = p.channel === 'gear' ? (hi - lo > 5 ? 2 : 1) : niceStep(hi - lo, h > 150 ? 5 : 3);
    for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) {
      const yy = sy(v);
      const zero = p.channel === 'deltaS' && Math.abs(v) < step / 1000;
      out.push(
        `<line x1="${left}" x2="${left + plotW}" y1="${n1(yy)}" y2="${n1(yy)}" stroke="${zero ? C.axis : C.grid}" stroke-width="1"/>`,
      );
      const label =
        p.channel === 'deltaS'
          ? v.toFixed(step < 0.1 ? 2 : 1).replace('.', ',')
          : `${Math.round(v * 100) / 100}`;
      out.push(
        `<text x="${left - 8}" y="${n1(yy + 4)}" fill="${C.muted}" font-size="11" text-anchor="end">${label}</text>`,
      );
    }
    // delta fill: red above zero (losing), blue below (gaining)
    if (p.channel === 'deltaS') {
      const vals = lines[0]!.vals;
      const y0 = sy(0);
      for (const [sign, color] of [
        [1, C.loss],
        [-1, C.gain],
      ] as const) {
        let d = `M${n1(sx(xs[0]!))},${n1(y0)}`;
        xs.forEach((x, i) => {
          const v = vals[i];
          const vv =
            v === null || v === undefined || !Number.isFinite(v)
              ? 0
              : sign > 0
                ? Math.max(0, v)
                : Math.min(0, v);
          d += `L${n1(sx(x))},${n1(sy(vv))}`;
        });
        d += `L${n1(sx(xs.at(-1)!))},${n1(y0)}Z`;
        out.push(`<path d="${d}" fill="${color}" fill-opacity="0.35" stroke="none"/>`);
      }
    }
    for (const l of lines) {
      let d = '';
      let pen = false;
      let prevY = 0;
      l.vals.forEach((v, i) => {
        if (v === null || !Number.isFinite(v)) {
          pen = false;
          return;
        }
        const px = n1(sx(xs[i]!));
        const py = sy(v);
        if (!pen) d += `M${px},${n1(py)}`;
        else if (p.step) d += `L${px},${n1(prevY)}L${px},${n1(py)}`;
        else d += `L${px},${n1(py)}`;
        pen = true;
        prevY = py;
      });
      out.push(
        `<path d="${d}" fill="none" stroke="${l.color}" stroke-width="${l.width}" stroke-linejoin="round" stroke-linecap="round"/>`,
      );
    }
    out.push(
      `<text x="${left + 8}" y="${y + 15}" fill="${C.text2}" font-size="12" font-weight="600" stroke="${C.panel}" stroke-width="4" paint-order="stroke">${esc(p.title)}</text>`,
    );
    y += h + gap;
  }
  const plotBottom = y - gap;

  // corner markers across all panels
  let lastLabelX = Number.NEGATIVE_INFINITY;
  for (const m of input.markers) {
    if (m.distanceM < from || m.distanceM > to) continue;
    const x = n1(sx(m.distanceM));
    const labelled = Number(x) - lastLabelX >= 26;
    if (labelled) lastLabelX = Number(x);
    out.push(
      `<line x1="${x}" x2="${x}" y1="${top}" y2="${plotBottom}" stroke="${C.axis}" stroke-width="1" stroke-dasharray="3 4"/>`,
    );
    if (labelled) {
      out.push(
        `<text x="${x}" y="${top - 6}" fill="${C.text2}" font-size="11" text-anchor="middle">${esc(m.label)}</text>`,
      );
    }
  }
  // distance axis
  const dStep = niceStep(to - from, 10);
  for (let d = Math.ceil(from / dStep) * dStep; d <= to + 1e-6; d += dStep) {
    const x = n1(sx(d));
    out.push(
      `<line x1="${x}" x2="${x}" y1="${plotBottom}" y2="${plotBottom + 5}" stroke="${C.axis}"/>`,
    );
    out.push(
      `<text x="${x}" y="${plotBottom + 18}" fill="${C.muted}" font-size="11" text-anchor="middle">${Math.round(d)}</text>`,
    );
  }
  out.push(
    `<text x="${left + plotW}" y="${plotBottom + 34}" fill="${C.muted}" font-size="11" text-anchor="end">distância na volta (m)</text>`,
  );

  // ---- map ----
  const mapTop = top;
  const mapH = Math.max(360, Math.min(plotBottom - top, mapW * 1.15));
  out.push(
    `<rect x="${mapX}" y="${mapTop}" width="${mapW}" height="${mapH}" fill="${C.panel}" rx="4"/>`,
  );
  out.push(
    `<text x="${mapX + 10}" y="${mapTop + 18}" fill="${C.text2}" font-size="12" font-weight="600">${input.zoom ? 'Traçado na curva (zoom)' : 'Mapa: onde você perde / ganha'}</text>`,
  );
  const focus: MapPoint[] = input.zoom
    ? [...input.subject, ...input.reference]
    : input.track.length
      ? input.track
      : input.subject;
  if (focus.length > 1) {
    // view: X mirrored so that left turns look left (heading convention: + curvature = left)
    const vx = (p: MapPoint) => -p.x;
    const vy = (p: MapPoint) => -p.z;
    const minX = Math.min(...focus.map(vx));
    const maxX = Math.max(...focus.map(vx));
    const minY = Math.min(...focus.map(vy));
    const maxY = Math.max(...focus.map(vy));
    const pad = 26;
    const innerTop = mapTop + 30;
    const innerH = mapH - 30 - pad;
    const s = Math.min(
      (mapW - 2 * pad) / Math.max(1e-6, maxX - minX),
      innerH / Math.max(1e-6, maxY - minY),
    );
    const ox = mapX + pad + (mapW - 2 * pad - (maxX - minX) * s) / 2;
    const oy = innerTop + (innerH - (maxY - minY) * s) / 2;
    const px = (p: MapPoint) => n1(ox + (vx(p) - minX) * s);
    const py = (p: MapPoint) => n1(oy + (vy(p) - minY) * s);
    const path = (pts: MapPoint[], close = false) =>
      pts.map((p, i) => `${i ? 'L' : 'M'}${px(p)},${py(p)}`).join('') + (close ? 'Z' : '');
    out.push(
      `<clipPath id="mapclip"><rect x="${mapX}" y="${mapTop + 24}" width="${mapW}" height="${mapH - 24}"/></clipPath>`,
    );
    out.push('<g clip-path="url(#mapclip)">');
    const asphaltW = input.zoom ? Math.max(8, Math.min(40, 12 * s)) : 9;
    if (input.track.length > 1) {
      out.push(
        `<path d="${path(input.track, true)}" fill="none" stroke="${C.asphalt}" stroke-width="${n1(asphaltW)}" stroke-linejoin="round" stroke-linecap="round"/>`,
      );
    }
    // subject line colored by delta rate, grouped into runs of the same color
    const sub = input.subject;
    let run: MapPoint[] = [];
    let runColor = '';
    const flush = () => {
      if (run.length > 1) {
        out.push(
          `<path d="${path(run)}" fill="none" stroke="${runColor}" stroke-width="${input.zoom ? 4 : 4.5}" stroke-linejoin="round" stroke-linecap="round"/>`,
        );
      }
    };
    for (let i = 0; i < sub.length; i++) {
      const c = deltaColor(sub[i]!.rate);
      if (c !== runColor) {
        const last = run.at(-1);
        flush();
        run = last ? [last] : [];
        runColor = c;
      }
      run.push(sub[i]!);
    }
    flush();
    if (input.zoom && input.reference.length > 1) {
      out.push(
        `<path d="${path(input.reference)}" fill="none" stroke="${C.ref}" stroke-width="2.2" stroke-dasharray="7 5" stroke-linecap="round"/>`,
      );
    }
    for (const b of input.brakePoints ?? []) {
      const color = b.who === 'you' ? C.you : C.ref;
      out.push(
        `<rect x="${Number(px(b)) - 6}" y="${Number(py(b)) - 6}" width="12" height="12" rx="2" fill="${color}" stroke="${C.surface}" stroke-width="2"/>`,
      );
    }
    for (const c of input.corners) {
      const cx = Number(px(c));
      const cy = Number(py(c));
      if (cx < mapX || cx > mapX + mapW || cy < mapTop + 24 || cy > mapTop + mapH) continue;
      out.push(`<circle cx="${cx}" cy="${cy}" r="3" fill="${C.text}"/>`);
      out.push(
        `<text x="${cx + 7}" y="${cy - 6}" fill="${C.text}" font-size="12" font-weight="600" stroke="${C.panel}" stroke-width="3" paint-order="stroke">${esc(c.label)}</text>`,
      );
    }
    if (!input.zoom && input.track.length > 1) {
      const s0 = input.track[0]!;
      out.push(
        `<rect x="${Number(px(s0)) - 5}" y="${Number(py(s0)) - 5}" width="10" height="10" fill="${C.text}" stroke="${C.surface}" stroke-width="2"/>`,
      );
    }
    out.push('</g>');
  }
  // map legend
  let ly = mapTop + mapH + 22;
  const legend = (color: string, label: string, dash = false) => {
    out.push(
      `<line x1="${mapX}" x2="${mapX + 26}" y1="${ly - 4}" y2="${ly - 4}" stroke="${color}" stroke-width="4" ${dash ? 'stroke-dasharray="7 5"' : ''} stroke-linecap="round"/>`,
    );
    out.push(
      `<text x="${mapX + 34}" y="${ly}" fill="${C.text2}" font-size="12">${esc(label)}</text>`,
    );
    ly += 20;
  };
  legend(C.loss, 'você perdendo tempo (vermelho)');
  legend(C.gain, 'você ganhando tempo (azul)');
  legend(C.mid, 'neutro');
  if (input.zoom) {
    legend(C.ref, 'linha da referência', true);
    out.push(
      `<text x="${mapX}" y="${ly}" fill="${C.muted}" font-size="11">■ = ponto de frenagem (cor do piloto)</text>`,
    );
    ly += 18;
  } else {
    out.push(
      `<text x="${mapX}" y="${ly}" fill="${C.muted}" font-size="11">■ branco = largada/chegada</text>`,
    );
    ly += 18;
  }

  // ---- header + series legend ----
  const head: string[] = [];
  head.push(
    `<text x="${left}" y="34" fill="${C.text}" font-size="20" font-weight="700">${esc(input.title)}</text>`,
  );
  head.push(
    `<text x="${left}" y="56" fill="${C.text2}" font-size="13">${esc(input.subtitle)}</text>`,
  );
  let lx = left + plotW;
  for (const [color, label] of [
    [C.ref, input.refLabel],
    [C.you, input.youLabel],
  ] as const) {
    const wText = Math.min(260, label.length * 7 + 10);
    lx -= wText + 30;
    head.push(
      `<line x1="${lx}" x2="${lx + 22}" y1="30" y2="30" stroke="${color}" stroke-width="3" stroke-linecap="round"/>`,
    );
    head.push(`<text x="${lx + 28}" y="34" fill="${C.text}" font-size="13">${esc(label)}</text>`);
  }

  const footerY = Math.max(plotBottom + 56, ly + 10);
  const foot = (input.footer ?? []).map(
    (f, i) =>
      `<text x="${left}" y="${footerY + i * 17}" fill="${C.muted}" font-size="11">${esc(f)}</text>`,
  );
  const H = Math.ceil(footerY + (input.footer?.length ?? 0) * 17 + 8);
  return [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" font-family="${FONT}">`,
    `<rect width="${W}" height="${H}" fill="${C.surface}"/>`,
    ...head,
    ...out,
    ...foot,
    '</svg>',
  ].join('\n');
}

/** Rasterizes an SVG to PNG (system fonts, white text on the dark surface). */
export function svgToPng(svg: string, width?: number): Buffer {
  const r = new Resvg(svg, {
    background: C.surface,
    font: { loadSystemFonts: true, defaultFontFamily: 'Segoe UI' },
    ...(width ? { fitTo: { mode: 'width' as const, value: width } } : {}),
  });
  return Buffer.from(r.render().asPng());
}

export interface ComparisonChartRequest {
  lapId: Id;
  reference?: Id | ComparisonReferenceKind;
  cornerId?: string;
  channels?: ChartChannel[];
  /** Output width in px (default 1400). */
  width?: number;
}

export interface ComparisonChartResult {
  png: Buffer;
  svg: string;
  caption: string;
  comparison: LapComparisonResult;
}

const DEFAULT_CHART_CHANNELS: ChartChannel[] = [
  'speedKmh',
  'throttle',
  'brake',
  'gear',
  'steering',
  'deltaS',
];

function interpAt(xs: readonly number[], ys: readonly number[], x: number): number {
  if (xs.length === 0) return Number.NaN;
  if (x <= xs[0]!) return ys[0]!;
  if (x >= xs.at(-1)!) return ys.at(-1)!;
  let lo = 0;
  let hi = xs.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (xs[mid]! <= x) lo = mid;
    else hi = mid;
  }
  const t = (x - xs[lo]!) / (xs[hi]! - xs[lo]! || 1);
  return ys[lo]! + (ys[hi]! - ys[lo]!) * t;
}

/** Collects the data (comparison, chart series, map lines) and renders the PNG. */
export async function buildComparisonChart(
  analysis: AnalysisService,
  req: ComparisonChartRequest,
): Promise<ComparisonChartResult> {
  const cmp = await analysis.compareLaps(req.lapId, req.reference ?? 'auto');
  const lap = cmp.lap;
  const refLap = cmp.referenceLap;
  const trackAn = await analysis.getTrackAnalysis(lap.trackId!, { maxMapPoints: 900 });
  const zoom = !!req.cornerId;
  const chart = await analysis.getChartData([refLap.id, lap.id], {
    ...(req.cornerId ? { cornerId: req.cornerId } : {}),
    channels: req.channels?.length ? req.channels : DEFAULT_CHART_CHANNELS,
    maxPoints: zoom ? 300 : 700,
    referenceIndex: 0,
  });
  const [posA, posB, delta] = await Promise.all([
    analysis.getResampledTrace(lap.id, {
      fromM: chart.fromM,
      toM: chart.toM,
      stepM: 2,
      maxPoints: zoom ? 400 : 900,
      channels: ['x', 'z'],
    }),
    analysis.getResampledTrace(refLap.id, {
      fromM: chart.fromM,
      toM: chart.toM,
      stepM: 2,
      maxPoints: zoom ? 400 : 900,
      channels: ['x', 'z'],
    }),
    analysis.getDeltaTrace(lap.id, refLap.id, { stepM: 2 }),
  ]);
  const subject = posA.distanceM.map((d, i) => ({
    x: posA.channels.x![i]!,
    z: posA.channels.z![i]!,
    rate: interpAt(delta.distanceM, delta.rateSPer100m, d),
  }));
  const reference = posB.distanceM.map((_d, i) => ({
    x: posB.channels.x![i]!,
    z: posB.channels.z![i]!,
  }));
  const finite = (p: MapPoint) => Number.isFinite(p.x) && Number.isFinite(p.z);

  const cornerDef = req.cornerId
    ? findCorner(
        cmp.comparison.rows.map((r) => r.corner),
        req.cornerId,
      )
    : undefined;
  const corner = cornerDef
    ? cmp.comparison.rows.find((r) => r.corner.id === cornerDef.id)
    : undefined;
  if (zoom) {
    // zoomed delta: time lost inside the window (starts at 0)
    for (const s of chart.series) {
      if (s.channel !== 'deltaS') continue;
      const v0 = s.values.find((v) => v !== null) ?? 0;
      s.values = s.values.map((v) => (v === null ? null : Math.round((v - v0) * 1000) / 1000));
    }
  }
  const brakePoints: NonNullable<ComparisonChartInput['brakePoints']> = [];
  if (corner) {
    for (const [who, d, pos] of [
      ['you', corner.a.brakePointM, posA],
      ['ref', corner.b.brakePointM, posB],
    ] as const) {
      if (d === null) continue;
      const x = interpAt(pos.distanceM, pos.channels.x!, d);
      const z = interpAt(pos.distanceM, pos.channels.z!, d);
      if (Number.isFinite(x) && Number.isFinite(z)) brakePoints.push({ who, x, z });
    }
  }
  const markers = zoom
    ? chart.markers.map((m) => ({ label: m.label.replace(/^\S+ /, ''), distanceM: m.distanceM }))
    : chart.markers
        .filter((m) => m.label.endsWith('ápice'))
        .map((m) => ({ label: m.label.split(' ')[0]!, distanceM: m.distanceM }));
  const c = cmp.comparison;
  const trackName = trackAn.track.name;
  const refName = refLap.referenceMeta?.driverName ?? `volta ${refLap.number}`;
  const cornerLabel = corner
    ? `${corner.corner.id}${corner.corner.name ? ` (${corner.corner.name})` : ''}`
    : null;
  const title = cornerLabel
    ? `${trackName} · ${cornerLabel}: ${formatDelta(corner!.timeLostMs)}`
    : `${trackName} · você × ${refName}`;
  const subtitle =
    `Você ${formatLapTime(c.lapATimeMs)} × referência ${formatLapTime(c.lapBTimeMs)} → ` +
    `${formatDelta(c.totalDeltaMs, 3)}` +
    (c.sectorDeltasMs
      ? ` · setores ${c.sectorDeltasMs.map((v) => formatDelta(v)).join(' / ')}`
      : '');
  const footer: string[] = [];
  if (corner) {
    const f = corner.findings?.[0];
    if (f?.message) footer.push(`Diagnóstico: ${f.message}`);
    if (f?.action) footer.push(`Ação: ${f.action}`);
  } else {
    const top = c.topLosses.map((r) => `${r.corner.id} ${formatDelta(r.timeLostMs)}`).join(' · ');
    footer.push(`Curvas que mais custam: ${top}`);
  }
  if (c.referenceIsReplay) {
    footer.push(
      'Referência de replay: entradas suavizadas, distâncias com precisão de alguns metros.',
    );
  }
  if (lap.carCode !== refLap.carCode) footer.push('Atenção: carros diferentes.');
  const svg = renderComparisonSvg({
    title,
    subtitle,
    youLabel: `Você (${formatLapTime(lap.timeMs)})`,
    refLabel: `Referência: ${refName} (${formatLapTime(refLap.timeMs)})`,
    chart,
    lapId: lap.id,
    refLapId: refLap.id,
    track: trackAn.map ? trackAn.map.x.map((x, i) => ({ x, z: trackAn.map!.z[i]! })) : [],
    subject: subject.filter(finite),
    reference: reference.filter(finite),
    corners: trackAn.corners
      .filter((k) => Number.isFinite(k.apexX))
      .map((k) => ({
        id: k.id,
        label: k.name ? `${k.id} ${k.name}` : k.id,
        x: k.apexX,
        z: k.apexZ,
      })),
    zoom,
    brakePoints,
    markers,
    footer,
  });
  const png = svgToPng(svg, req.width);
  const caption =
    `Gráfico: ${cornerLabel ?? 'volta inteira'} · você (laranja) × referência (verde-água) · ` +
    `delta ${formatDelta(corner ? corner.timeLostMs : c.totalDeltaMs, 3)}. Painéis: ` +
    `${[...new Set(chart.series.map((s) => s.label))].join(', ')}; mapa colorido pelo ganho/perda de tempo.`;
  return { png, svg, caption, comparison: cmp };
}
